/**
 * Salow Workspace First-Party HTMX Runtime (Phase 1 Compliant)
 * Provides reliable, zero-dependency polling, swapping, and header-based redirects
 * strictly conforming to hx-get, hx-post, hx-trigger ("every Xs"), hx-target, hx-swap, and HX-Redirect.
 */
(function(window, document) {
  'use strict';

  function getCookie(name) {
    var cookieValue = null;
    if (document.cookie && document.cookie !== '') {
      var cookies = document.cookie.split(';');
      for (var i = 0; i < cookies.length; i++) {
        var cookie = cookies[i].trim();
        if (cookie.substring(0, name.length + 1) === (name + '=')) {
          cookieValue = decodeURIComponent(cookie.substring(name.length + 1));
          break;
        }
      }
    }
    return cookieValue;
  }

  function getCsrfToken() {
    return getCookie('__Host-csrftoken') || getCookie('csrftoken') || (document.querySelector('input[name="csrfmiddlewaretoken"]') ? document.querySelector('input[name="csrfmiddlewaretoken"]').value : '');
  }

  function swapContent(target, html, swapStyle) {
    if (!target) return;
    swapStyle = (swapStyle || 'innerHTML').trim();
    if (swapStyle === 'outerHTML') {
      var temp = document.createElement('div');
      temp.innerHTML = html;
      var newEl = temp.firstElementChild;
      if (newEl && target.parentNode) {
        target.parentNode.replaceChild(newEl, target);
        htmx.process(newEl);
      }
    } else {
      target.innerHTML = html;
      htmx.process(target);
    }
  }

  function executeRequest(el) {
    var url = el.getAttribute('hx-get') || el.getAttribute('hx-post');
    var method = el.getAttribute('hx-post') ? 'POST' : 'GET';
    if (!url) return;

    var targetSelector = el.getAttribute('hx-target');
    var target = targetSelector ? (targetSelector === 'this' ? el : document.querySelector(targetSelector)) : el;
    var swapStyle = el.getAttribute('hx-swap') || 'innerHTML';

    var xhr = new XMLHttpRequest();
    xhr.open(method, url, true);
    xhr.setRequestHeader('HX-Request', 'true');
    xhr.setRequestHeader('X-Requested-With', 'XMLHttpRequest');

    if (method === 'POST') {
      var token = getCsrfToken();
      if (token) xhr.setRequestHeader('X-CSRFToken', token);
      xhr.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded');
    }

    xhr.onreadystatechange = function() {
      if (xhr.readyState === XMLHttpRequest.DONE) {
        var hxRedirect = xhr.getResponseHeader('HX-Redirect');
        if (hxRedirect) {
          window.location.href = hxRedirect;
          return;
        }
        if (xhr.status >= 200 && xhr.status < 400) {
          swapContent(target, xhr.responseText, swapStyle);
        } else if (xhr.status === 429) {
          swapContent(target, '<div class="alert alert-error">Rate limited. Please wait.</div>', swapStyle);
        }
      }
    };

    var bodyData = null;
    if (method === 'POST') {
      var formData = [];
      var token = getCsrfToken();
      if (token) formData.push('csrfmiddlewaretoken=' + encodeURIComponent(token));
      if (el.tagName === 'FORM') {
        var inputs = el.querySelectorAll('input, select, textarea');
        for (var i = 0; i < inputs.length; i++) {
          if (inputs[i].name && !inputs[i].disabled) {
            formData.push(encodeURIComponent(inputs[i].name) + '=' + encodeURIComponent(inputs[i].value));
          }
        }
      }
      bodyData = formData.join('&');
    }

    xhr.send(bodyData);
  }

  var htmx = {
    version: '1.9.12-salow',
    process: function(root) {
      root = root || document.body;
      if (!root) return;

      var elements = root.querySelectorAll ? Array.prototype.slice.call(root.querySelectorAll('[hx-get], [hx-post]')) : [];
      if (root.hasAttribute && (root.hasAttribute('hx-get') || root.hasAttribute('hx-post'))) {
        elements.push(root);
      }

      elements.forEach(function(el) {
        if (el._htmx_bound) return;
        el._htmx_bound = true;

        var trigger = (el.getAttribute('hx-trigger') || '').trim();

        if (trigger.indexOf('every ') === 0) {
          var match = trigger.match(/^every\s+(\d+(?:\.\d+)?)(s|ms)$/);
          if (match) {
            var val = parseFloat(match[1]);
            var intervalMs = match[2] === 's' ? val * 1000 : val;
            var timerId = setInterval(function() {
              if (!document.body.contains(el)) {
                clearInterval(timerId);
                return;
              }
              executeRequest(el);
            }, intervalMs);
          }
        } else if (trigger === 'load') {
          executeRequest(el);
        } else {
          var eventName = trigger || (el.tagName === 'FORM' ? 'submit' : 'click');
          el.addEventListener(eventName, function(e) {
            if (el.tagName === 'FORM' || el.tagName === 'A') {
              e.preventDefault();
            }
            executeRequest(el);
          });
        }
      });
    },
    ajax: function(method, url, context) {
      var dummy = document.createElement('div');
      dummy.setAttribute('hx-' + method.toLowerCase(), url);
      if (context && context.target) dummy.setAttribute('hx-target', context.target);
      if (context && context.swap) dummy.setAttribute('hx-swap', context.swap);
      executeRequest(dummy);
    }
  };

  window.htmx = htmx;

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function() {
      htmx.process(document.body);
    });
  } else {
    htmx.process(document.body);
  }
})(window, document);
